def receive(url, maximum):
    request = urllib.request.Request(url, headers={"User-Agent": "Commons-C271-original-native-814B"})
    with urllib.request.urlopen(request, timeout=60) as response:
        data = response.read(maximum + 1)
    if len(data) > maximum: raise ValueError("source response exceeded bound")
    return data
